from smart_contracts.deploy_common import deploy_typed


# Deploys ConflictRegistry, funds it for box storage and records its app id in
# smart_contracts/artifacts/deployed_apps.json (read by the API).
# The typed client is generated by `algokit project run build`.
def deploy() -> None:
    from smart_contracts.artifacts.conflict_registry.conflict_registry_client import (
        ConflictRegistryFactory,
    )

    deploy_typed("conflict_registry", ConflictRegistryFactory)
